const MT=[{n:'新人賽',fee:20,prize:90,rep:3,en:'街頭小混混',hp:50,atk:5},{n:'地區賽',fee:60,prize:260,rep:6,en:'地區拳擊手',hp:75,atk:8},{n:'全國賽',fee:150,prize:700,rep:11,en:'全國亞軍',hp:105,atk:12},
 {n:'洲際賽',fee:400,prize:1800,rep:17,en:'洲際衛冕者',hp:140,atk:17},{n:'世界賽',fee:1000,prize:4500,rep:26,en:'世界排名第一',hp:185,atk:23},{n:'傳奇賽',fee:2500,prize:12000,rep:40,en:'傳說中的格鬥王',hp:240,atk:30}];
