const CLS=mkSpr(160,80,c=>{const r=c.createRadialGradient(80,40,5,80,40,78);r.addColorStop(0,'rgba(20,30,50,.5)');r.addColorStop(1,'rgba(20,30,50,0)');c.fillStyle=r;c.save();c.scale(1,.5);c.translate(0,40);c.fillRect(0,-40,160,160);c.restore()});
function clouds(){const w=wx();if(w!=1&&w!=2)return;for(let i=0;i<7;i++){const wx0=((i*337+NOW*(.006+i*.0007))%(WW+400))-200,wy0=(i*251)%WH;const sx=wx0-CAM.x,sy=wy0-CAM.y;if(sx>-170&&sx<W+10&&sy>-90&&sy<H+10){g.globalAlpha=w==2?.9:.6;g.drawImage(CLS,sx-40,sy-20,200,100);g.globalAlpha=1}}}
const RP=Array.from({length:150},()=>({x:Math.random()*W,y:Math.random()*H,v:240+Math.random()*120})),LV=Array.from({length:34},()=>({x:Math.random()*W,y:Math.random()*H,s:30+Math.random()*40,ph:Math.random()*7,c:Math.random()<.5?'#6cc35a':'#f08cb6'})),RIP=[];
function weatherFx(dt){const w=wx();
 if(w==2){g.save();g.lineWidth=.55;g.strokeStyle='rgba(200,220,255,.55)';g.beginPath();RP.forEach(r=>{r.y+=r.v*dt;r.x-=r.v*dt*.18;if(r.y>H){r.y=-8;r.x=Math.random()*(W+40)}if(r.x<-10)r.x+=W+20;g.moveTo(r.x,r.y);g.lineTo(r.x+1.6,r.y-7)});g.stroke();
  if(Math.random()<.6)RIP.push({x:Math.random()*W,y:80+Math.random()*(H-80),t:0});for(let i=RIP.length-1;i>=0;i--){const q=RIP[i];q.t+=dt;if(q.t>.5){RIP.splice(i,1);continue}g.strokeStyle=`rgba(210,230,255,${.5*(1-q.t*2)})`;g.beginPath();g.ellipse(q.x,q.y,1+q.t*7,.5+q.t*3,0,0,7);g.stroke()}g.restore()}
 if(w==3){g.save();LV.forEach(l=>{l.x+=l.s*dt*2.2;l.y+=Math.sin(NOW/300+l.ph)*.6+dt*8;if(l.x>W+8){l.x=-8;l.y=Math.random()*H}if(l.y>H)l.y=-4;g.fillStyle=l.c;g.save();g.translate(l.x,l.y);g.rotate(NOW/200+l.ph);g.beginPath();g.ellipse(0,0,2.2,1.1,0,0,7);g.fill();g.restore()});
  g.strokeStyle='rgba(255,255,255,.12)';g.lineWidth=.5;g.beginPath();for(let i=0;i<10;i++){const y=(i*53+NOW*.05)%H,x=((NOW*.3)+i*97)%(W+60)-30;g.moveTo(x,y);g.lineTo(x+22,y+(i%2?1.5:-1.5))}g.stroke();g.restore()}}
