const dirTxt=(tx,ty)=>{const dx=tx-p.x,dy=ty-p.y,d=Math.round(Math.hypot(dx,dy)/4),h=Math.abs(dx)<24?'':dx>0?'東':'西',v=Math.abs(dy)<24?'':dy>0?'南':'北';return `在你的${v}${h}方，約 ${d} 公尺，靠近「${placeName(tx,ty)}」。門都開在建築南側。`};
function depo(n){const a=Math.min(n,st.money);st.money-=a;st.bank+=a;hud();toast('🏦 已存入 💰'+a)}
function wdr(n){const a=Math.min(n,st.bank);st.bank-=a;st.money+=a;hud();toast('🏦 已提領 💰'+a)}
const bankOpts=()=>{const o=[];[100,500].forEach(n=>o.push([`💰 存款 ${n}`,'每天利息約 1%',()=>{depo(n);mainMenu('銀行')},st.money<n]));
 o.push([`💰 存入全部（💰${st.money}）`,'',()=>{depo(st.money);mainMenu('銀行')},st.money<1]);
 [100,500].forEach(n=>o.push([`📤 提款 ${n}`,'',()=>{wdr(n);mainMenu('銀行')},st.bank<n]));
 o.push([`📤 提領全部（🏦${st.bank}）`,'',()=>{wdr(st.bank);mainMenu('銀行')},st.bank<1]);return o};
