function policeOpts(){const o=[];
 o.push(['🗺️ 問路（想去哪裡？）','員警會告訴你方向與距離',()=>askWay()]);
 if(RACE.seen&&!RACE.reported)o.push(['🚨 報案：有人在大馬路上飆車','協助警方，⭐+6 💰+80',()=>{RACE.reported=1;fxApply({r:6,m:80,j:3});hud();closeDlg();toast('📞 警方已派員處理，感謝你的通報！')}]);
 o.push(['📋 交通安全小常識','🧠+1',()=>{fxApply({w:1});hud();const tips=['過馬路請走斑馬線，看行人號誌的倒數秒數。','晚上十一點後，大馬路偶爾會有人飆車，千萬別在路邊逗留。','路口左右看，行人也要遵守紅綠燈。','騎機車一定要戴安全帽，開車繫安全帶。'];openDlg('📋 交通安全','「'+tips[Math.random()*4|0]+'」',[['返回','',cancel]],true)}]);
 return o}
function askWay(){const o=B.filter(b=>IN[b.n]).map(b=>[`${I[b.n]||'🏢'} ${b.sg||b.n}`,'',()=>openDlg('🗺️ 指路',`「${b.sg||b.n}嗎？${dirTxt(b.x+b.dx,b.bot+10)}」`,[['謝謝','',cancel]],true)]);o.push(['返回','',cancel]);openDlg('🗺️ 想去哪裡？','請選擇目的地：',o,true)}
function policeMenu(n,line){const o=policeOpts();o.push(['💼 警務職涯・'+(st.cp==11?jobName():'應徵／職涯'),'上班、晉升、轉職',()=>career(11)]);o.push(['💬 閒聊','',()=>{openDlg('💬 '+n.n,say(n),[['返回','',cancel]],true)}]);o.push(['離開','',closeDlg]);openDlg('🚓 '+n.n,line+'<br><span class="opacity-70">（警察可以問路、通報飆車、應徵警務）</span>',o)}
