const MIND={hungry:['（肚子餓餓的……）','（咕嚕嚕——牠的肚子在叫。）','（眼睛直盯著你的口袋，好像在找吃的。）'],sleepy:['（累累的，想睡覺了……）','（眼皮一直往下掉。）','（打了一個大大的哈欠。）'],happy:['（心情很好，整個身體都在搖擺！）','（開心得原地轉圈圈。）','（靠過來蹭了蹭你。）'],bored:['（有點無聊，想要有人陪牠玩……）','（東張西望，好像在等什麼。）'],calm:['（安安靜靜地待著，看起來很放鬆。）','（舒服地瞇起眼睛。）','（偶爾抖一抖耳朵。）'],lonely:['（想你了……一直望著你。）','（靠得很近，不想分開。）']};
const pick2=a=>a[(Math.random()*a.length)|0];
function petMood(n,pt){const h=T.hour;if(pt){if(pt.hap<30)return 'lonely';if(pt.hap<50)return 'bored'}
 if(h>=22||h<5)return 'sleepy';const r=Math.random();if(pt&&pt.hap>=80&&r<.5)return 'happy';if((h>=11&&h<13||h>=17&&h<19)&&r<.6)return 'hungry';if(h>=13&&h<15&&r<.4)return 'sleepy';return pick2(['calm','calm','bored','happy','hungry'])}
function petTalk(n){const k=n.pk||n.t,info=ANI[n.t]||ANI.cat,sp=PETS[n.pk]||null,id=(n.pk||n.t)+'|'+(n.c||''),isCo=n===PET&&st.comp,pt=isCo?compPet():(n.ptid?petOf(n.ptid):null);
 const nm=pt?pt.name:n.n||(sp?sp.n:'小動物'),first=!st.seen['an_'+id];st.seen['an_'+id]=1;
 let desc;if(first){desc=`${info.i} <b>${sp?sp.n:nm}</b><br>${sp?sp.d+'<br>':''}${info.d}<br><i>（第一次見面，你仔細地端詳著牠。）</i>`}
 else desc=`<i>${pick2(info.me)}</i><br><i>${nm}：${pick2(MIND[petMood(n,pt)])}</i>`;
 const o=[['🤲 摸摸','😊+2',()=>{fxApply({j:2});if(pt)pt.hap=Math.min(100,pt.hap+3);hud();openDlg('💬 '+(n.n||nm),`<i>${pick2(info.me)}</i><br><i>${nm}：${pick2(MIND[pt&&pt.hap>=70?'happy':'calm'])}</i>`,[['返回','',closeDlg]])}]];
 if(pt)o.push(['🥫 餵食','需要飼料',()=>{if(!(st.inv.food>0))return;st.inv.food--;pt.hap=Math.min(100,pt.hap+15);hud();openDlg('💬 '+(n.n||nm),`<i>（把飼料遞過去，${nm}吃得津津有味。）</i><br><i>${nm}：（滿足地舔了舔嘴巴。）</i>`,[['返回','',closeDlg]])},!(st.inv.food>0)]);
 o.push(['離開','',closeDlg]);openDlg('💬 '+(n.n||nm),desc,o)}

