 if(INC&&INC.st=='new'&&!INC.rep)o.push([`📞 立即報案：${INCT[INC.k].ic}${INCT[INC.k].n}（${INCT[INC.k].tel}）`,'目前有未通報的事件',()=>{reportInc(1);closeDlg()}]);
