function startCafeDay(){st.cafe=2;st.cafeN=0;st.cafeDone={};if(scene=='咖啡店'){rm.ppl=rm.ppl.filter(n=>!n.sf)}
 seq('保羅',[['保羅','「太好了！仰恩，要乖乖聽大哥哥的話喔。」'],['仰恩','「好～～！大哥哥我們先玩什麼？」']],()=>{toast('🧸 陪仰恩玩：到右下角的遊戲區和仰恩互動，一共要玩 5 項遊戲');setTimeout(cafeKid,200)})}
