function cafeKid(){
 if(st.cafe==2){const left=KACT.filter(a=>!st.cafeDone[a.k]),n=st.cafeN;
  if(n>=5)return finishCafeDay();
  const o=left.map(a=>[`${a.i} ${a.n}（${a.h} 小時）`,a.d,()=>kidAct(a),st.sta<8]);o.push(['離開（稍後再回來）','',closeDlg]);
  return openDlg('💬 仰恩',`<i>仰恩拉著你的衣角。</i><br>「大哥哥，我們要玩什麼？」<br><span style="font-size:12px;opacity:.7">陪玩進度 ${n}/5　⚡ ${st.sta}</span>`,o)}
 if(st.cafe==1)return cafeOffer();
 const o=[['🧱 陪仰恩玩一小時','😊+8 ⚡-5',()=>{fxApply({j:8,s:-5});advance(1);hud();closeDlg();toast('🧸 仰恩笑得很開心。')},st.sta<5],['離開','',closeDlg]];
 openDlg('💬 仰恩',st.cafe>=3?'「大哥哥！你來啦！今天玩什麼？」':'「大哥哥！等爸爸答應了我們再一起玩！」',o)}
function kidAct(a){const o=a.o.map(q=>[q[0],'',()=>{st.cafeDone[a.k]=1;st.cafeN++;fxApply({s:-8,j:6,r:1});advance(a.h);hud();
  seq('仰恩',[['仰恩','<i>'+q[1]+'</i>'],['仰恩',['「好好玩喔！」','「大哥哥你最棒了！」','「再玩一次好不好？」'][(Math.random()*3)|0]]],()=>setTimeout(cafeKid,150))}]);
 openDlg('💬 仰恩',a.i+' '+a.n+'：'+a.d,o)}
