 for(let i=solids.length-1;i>=0;i--){const o=solids[i],cx=o.x+o.w/2,cy=o.y+o.h/2;if(cx>ent[0]&&cx<ent[1]&&cy>ent[2]&&cy<ent[3])solids.splice(i,1)}
