function gzNomW(k){if(EDW[k])return EDW[k];if(typeof PKN!='undefined'&&PKN[k])return PKN[k][1];if(k.startsWith('lf_')&&typeof LFMETA!='undefined'&&LFMETA[k])return Math.round(LFMETA[k][2]*.3);if(k.startsWith('ns_'))return 70;if(/^vh_k_\d+_s/.test(k))return 42;if(/^vh_k_/.test(k))return 22;if(k=='vh_i_engine')return 70;if(k=='vh_i_amb')return 50;if(k.startsWith('iv_c_mov'))return 40;if(/^(iv|ch|sh|en|sc|pf|mo)_/.test(k))return 28;if(EDCAT[0][1].includes(k))return EDW.statue;if(EDCAT[1][1].includes(k))return EDW.tree;if(UAM[k]&&!k.startsWith('lo_'))return UAM[k][0];
 if(EFLATK.has(k))return k.includes('curb')?26:18;if(k.includes('planter'))return 26;if(k.includes('hedge'))return 30;if(k.includes('rock'))return 16;if(k.includes('flower'))return 18;return 24}
// ── 建立可編輯物件清單 ──
function gzIndex(){if(ED.ready)return;ED.ready=1;
 for(const k in UAI)EKEY.set(UAI[k],k);
 const used=new Set(),seen={};
 const sig=(k,cx,by)=>{let s=k+'@'+Math.round(cx)+','+Math.round(by);if(seen[s]){seen[s]++;s+='#'+seen[s]}else seen[s]=1;return s};
 const findSol=(cx,by,w)=>{let best=null,bd=1e9;solids.forEach(s=>{if(used.has(s)||s.w>w+10||s.h>16)return;const sb=s.y+s.h;if(sb<by-12||sb>by+4)return;const sc=s.x+s.w/2,d=Math.abs(sc-cx);if(d<Math.max(8,w/2)&&d<bd){bd=d;best=s}});if(best)used.add(best);return best};
 const isLamp=d=>(typeof lampSpr!='undefined'&&d.spr===lampSpr)||EKEY.get(d.spr)=='st_lamp'||EKEY.get(d.spr)=='st_light';
 DEC.forEach(d=>{if(d.__pk&&!d.__uk&&typeof VUC!='undefined'){for(const q in VUC){if(VUC[q].img===d.spr){d.__uk=q.split('|')[0];break}}}const k=EKEY.get(d.spr)||('p'+Math.round(d.w)+'x'+Math.round(d.h)),by=d.by??d.y+d.h,cx=d.x+d.w/2;
  const e={kind:'dec',o:d,k,sig:sig(k,cx,by),sol:findSol(cx,by,d.w),lamp:null};
  if(isLamp(d)){let bd=30;LAMPS.forEach(l=>{const dd=Math.hypot(l[0]-(d.x+d.w*.7),l[1]-(d.y+6));if(dd<bd){bd=dd;e.lamp=l}})}
  gzOrig(e);if(d.__uk)e.k=d.__uk;EO.push(e)});
 trees.forEach(t=>{const cx=t.x+14,by=t.y+38;const e={kind:'tree',o:t,k:'tree'+(t.k||0),sig:sig('tree',cx,by),sol:null,lamp:null};
  let bd=1e9;solids.forEach(s=>{if(used.has(s))return;const d=Math.abs(s.x-(t.x+10))+Math.abs(s.y-(t.y+28));if(d<4&&d<bd){bd=d;e.sol=s}});if(e.sol)used.add(e.sol);gzOrig(e);EO.push(e)})}
function gzPose(e){if(e.kind=='tree')return{cx:e.o.x+14,by:e.o.y+38,s:(e.o.sc||1)/(e.O.sc||1)};const d=e.o,by=d.by??d.y+d.h;return{cx:d.x+d.w/2,by,s:d.w/e.O.w}}
function gzOrig(e){const o=e.o;e.O=e.kind=='tree'?{x:o.x,y:o.y,sc:o.sc||1}:{x:o.x,y:o.y,w:o.w,h:o.h,by:o.by};const p=gzPose(e);e.O.cx=p.cx;e.O.by=p.by;
 if(e.sol)e.O.sol={x:e.sol.x,y:e.sol.y,w:e.sol.w,h:e.sol.h};if(e.lamp)e.O.lamp=[e.lamp[0],e.lamp[1]];e.rm=0;e.flat=0;e.sd=e.sol?1:0;e.O.hs=e.sd;e.mx=0;if(e.kind!='tree')e.spr0=o.spr}
function gzBox(e){if(e.kind=='tree'){const t=e.o,k=UATREE[t.k]||'t_oak',m=UAM[k]||[56,70],sc=(t.sc||1)*(k=='t_pine'?1.05:1),w=m[0]*sc*.92,h=m[1]*sc*.92;return{x:t.x+14-w/2,y:t.y+38-h,w,h}}const d=e.o;return{x:d.x,y:d.y,w:d.w,h:d.h}}
function gzSet(e,cx,by,s){const O=e.O;
 if(e.kind=='tree'){e.o.x=cx-14;e.o.y=by-38;e.o.sc=O.sc*s}
 else{const d=e.o,w=O.w*s,h=O.h*s;d.w=w;d.h=h;d.x=cx-w/2;d.y=by-h;d.by=by}
 const mf=e.mx?-1:1;if(e.sol&&O.sol){e.sol.w=O.sol.w*s;e.sol.x=cx+(O.sol.x+O.sol.w/2-O.cx)*s*mf-e.sol.w/2;e.sol.y=by+(O.sol.y-O.by);e.sol.h=O.sol.h}
 if(e.lamp&&O.lamp){e.lamp[0]=cx+(O.lamp[0]-O.cx)*s*mf;e.lamp[1]=by+(O.lamp[1]-O.by)*s}}
const arrDel=(a,x)=>{const i=a.indexOf(x);if(i>=0)a.splice(i,1)};
function gzShow(e,on){const A=e.kind=='tree'?trees:(e.flat?FLATS:DEC);
 if(on){if(!A.includes(e.o))A.push(e.o);if(e.sol&&e.sd&&!solids.includes(e.sol))solids.push(e.sol);if(e.lamp&&!LAMPS.includes(e.lamp))LAMPS.push(e.lamp)}
 else{arrDel(A,e.o);if(e.sol)arrDel(solids,e.sol);if(e.lamp)arrDel(LAMPS,e.lamp)}}
function gzSetFlat(e,f){if(e.kind=='tree'||!!e.flat==!!f)return;const vis=!e.rm;if(vis)gzShow(e,0);e.flat=f?1:0;if(f)e.sd=0;if(vis)gzShow(e,1)}
function gzSetSolid(e,f){if(e.kind=='tree'&&!e.sol)return;if(!e.sol){const b=gzBox(e),p=gzPose(e);e.sol={x:p.cx-b.w*.35,y:p.by-6,w:b.w*.7,h:5};e.O.sol={x:e.O.cx-(b.w/p.s)*.35,y:e.O.by-6,w:(b.w/p.s)*.7,h:5}}
 e.sd=f?1:0;if(f)e.flat=0;if(!e.rm){if(f){if(!solids.includes(e.sol))solids.push(e.sol)}else arrDel(solids,e.sol)}}
// 新增物件
let EADD=0;
function gzAdd(k,cx,by,w,fl){if(!uaOK(k))return null;const im=UAI[k],h=w*im.naturalHeight/im.naturalWidth;const d={spr:im,x:cx-w/2,y:by-h,w,h,by};
 const e={kind:'dec',o:d,k,sig:'+'+(++EADD),add:1,sol:null,lamp:null,spr0:im,mx:0};e.O={x:d.x,y:d.y,w,h,by,cx,sc:1,hs:0};e.rm=0;e.flat=fl?1:0;e.sd=0;
 if(/lamp|st_light/.test(k)){e.lamp=[cx+(k=='st_lamp'?w*.25:0),by-h+4];e.O.lamp=[e.lamp[0],e.lamp[1]]}
 if(!fl&&!/flower_small|n_f|n_grass|n_fern/.test(k)){e.sol={x:cx-w*.35,y:by-6,w:w*.7,h:5};e.O.sol={...e.sol};e.sd=1}
 if(EDCAT[1][1].includes(k)&&e.sol){e.sol.w=w*.2;e.sol.x=cx-w*.1;e.O.sol={...e.sol}}
 EO.push(e);gzShow(e,1);return e}
// ── 地板 ──
function gzCellOK(ci){const cy=Math.floor(ci/ECW),cx=ci-cy*ECW,r={x:cx*EDC,y:cy*EDC,w:EDC,h:EDC};return !BOV.some(o=>hit(r,{x:o.x+2,y:o.y,w:o.w-4,h:o.h-1}))}
function gzCellRect(ci){const cy=Math.floor(ci/ECW),cx=ci-cy*ECW,x0=Math.round(cx*EDC*KS),y0=Math.round((cy*EDC+NY)*KS);return[x0,y0,Math.round((cx+1)*EDC*KS)-x0,Math.round(((cy+1)*EDC+NY)*KS)-y0]}
function gzPaintCell(ci,t){const r=gzCellRect(ci),x=S.getContext('2d');x.save();x.setTransform(1,0,0,1,0,0);
 if(!EFB.has(ci))EFB.set(ci,x.getImageData(r[0],r[1],r[2],r[3]));else x.putImageData(EFB.get(ci),r[0],r[1]);
 if(t){const pat=ltPat(x,t,ETS[t]||24);if(pat){try{pat.setTransform(new DOMMatrix())}catch(e){}x.fillStyle=pat;x.fillRect(r[0],r[1],r[2],r[3])}}
 x.restore();if(t)EFL[ci]=t;else delete EFL[ci]}
// ── 存檔格式 ──
function gzSerialize(){const m={v:1,t:Date.now(),rm:[],mv:{},add:[],fl:{}};const r2=v=>Math.round(v*10)/10;
 EO.forEach(e=>{if(e.add){if(!e.rm){const p=gzPose(e);m.add.push([e.k,r2(p.cx),r2(p.by),r2(e.o.w),(e.sd?1:0)|(e.flat?2:0)|(e.mx?4:0)])}return}
  if(e.rm){m.rm.push(e.sig);return}const p=gzPose(e),f=(e.sd?1:0)|(e.flat?2:0)|(e.mx?4:0),f0=e.O.hs?1:0;
  if(Math.abs(p.cx-e.O.cx)>.05||Math.abs(p.by-e.O.by)>.05||Math.abs(p.s-1)>.001||f!=f0)m.mv[e.sig]=[r2(p.cx),r2(p.by),Math.round(p.s*1000)/1000,f]});
 const by={};for(const ci in EFL)(by[EFL[ci]]=by[EFL[ci]]||[]).push(+ci);
 for(const t in by){const a=by[t].sort((u,v)=>u-v),out=[];let prev=0,i=0;while(i<a.length){let j=i;while(j+1<a.length&&a[j+1]==a[j]+1)j++;const n=j-i+1;out.push((a[i]-prev).toString(36)+(n>1?'*'+n.toString(36):''));prev=a[j];i=j+1}m.fl[t]=out.join(',')}
 return m}
function gzReset(){EO.slice().forEach(e=>{if(e.add){gzShow(e,0);arrDel(EO,e);return}
  if(e.rm){e.rm=0;gzSetFlat(e,0);gzShow(e,1)}else gzSetFlat(e,0);gzSetMx(e,0);const O=e.O;gzSet(e,O.cx,O.by,1);
  if(e.sol){if(O.sol){Object.assign(e.sol,O.sol)}e.sd=O.hs?1:0;if(e.sd){if(!solids.includes(e.sol))solids.push(e.sol)}else arrDel(solids,e.sol)}});
 Object.keys(EFL).forEach(ci=>gzPaintCell(+ci,null));EFL={};ED.sel=null}
function gzApply(m){if(!m||m.v!=1)return;gzIndex();gzReset();const bySig={};EO.forEach(e=>bySig[e.sig]=e);
 (m.rm||[]).forEach(s=>{const e=bySig[s];if(e){e.rm=1;gzShow(e,0)}});
 for(const s in m.mv||{}){const e=bySig[s];if(!e||e.rm)continue;const q=m.mv[s];gzSetMx(e,q[3]&4);gzSet(e,q[0],q[1],q[2]);if(e.kind!='tree'){gzSetFlat(e,q[3]&2);gzSetSolid(e,q[3]&1)}else if(e.sol){gzSetSolid(e,q[3]&1)}}
 (m.add||[]).forEach(q=>{const e=gzAdd(q[0],q[1],q[2],q[3],q[4]&2);if(e&&!(q[4]&1))gzSetSolid(e,0);if(e&&(q[4]&4))gzSetMx(e,1)});
 for(const t in m.fl||{}){let v=0;String(m.fl[t]).split(',').forEach(d=>{if(!d)return;const q=d.split('*'),n=q[1]?parseInt(q[1],36):1;v+=parseInt(q[0],36);for(let k=0;k<n;k++)gzPaintCell(v+k,t);v+=n-1})}
 ED.undo=[];ED.dirty=0}
// ── 讀取與儲存（共用資料庫 → 這台裝置 → 內建） ──
const EDLS='ptown-map-v1';
async function gzDb(){try{if(typeof claude=='undefined'||!claude.use)return null;return await claude.use('db')}catch(e){return null}}
async function gzLoadRemote(){const db=await gzDb();if(!db)return null;try{const s=await db.doc('world/map').get();if(!s.exists)return null;const d=s.data();let str='';
 for(let i=0;i<(d.n||0);i++){const p=await db.doc('world/map/parts/p'+i).get();if(!p.exists)return null;str+=p.data().s||''}return JSON.parse(str)}catch(e){return null}}
async function gzSaveRemote(m){const db=await gzDb();if(!db)return 'nodb';const str=JSON.stringify(m),N=180000,parts=[];for(let i=0;i<str.length;i+=N)parts.push(str.slice(i,i+N));
 try{for(let i=0;i<parts.length;i++)await db.doc('world/map/parts/p'+i).set({s:parts[i]});await db.doc('world/map').set({n:parts.length,t:m.t,v:1});return 'ok'}catch(e){return (e&&e.code)||'err'}}
function gzBoot(){try{gzIndex();let m=MAP_BAKED,loc=null;try{loc=JSON.parse(localStorage.getItem(EDLS)||'null')}catch(e){}
 if(loc&&(!m||loc.t>(m.t||0)))m=loc;if(m)gzApply(m);ED.cur=m?m.t||0:0;
 gzLoadRemote().then(r=>{if(r&&r.t&&r.t!=ED.cur&&!ED.on){gzApply(r);ED.cur=r.t;try{localStorage.setItem(EDLS,JSON.stringify(r))}catch(e){}}})}catch(e){console.error('gzBoot',e)}}
{const _b=buildBOV;buildBOV=function(){const r=_b.apply(this,arguments);if(!ED.booted){ED.booted=1;setTimeout(gzBoot,0)}return r}}
// 貼地物件畫在最底層
{const _sd=safetyDraw;safetyDraw=function(a){if(FLATS.length)a.push({y:-1e9,f:()=>FLATS.forEach(d=>{if(d.x+d.w>CAM.x-20&&d.x<CAM.x+W+20&&d.y+d.h>CAM.y-20&&d.y<CAM.y+H+20)g.drawImage(d.spr,d.x,d.y,d.w,d.h)})});return _sd.apply(this,arguments)}}

// ── 鏡像（左右翻轉）──
const GZFLIP=new Map();
function gzFlipSpr(im){let c=GZFLIP.get(im);if(c)return c;const w=im.naturalWidth||im.width,h=im.naturalHeight||im.height;c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.translate(w,0);x.scale(-1,1);x.drawImage(im,0,0);GZFLIP.set(im,c);return c}
function gzSetMx(e,f){f=f?1:0;if(!!e.mx==!!f)return;const p=gzPose(e);e.mx=f;if(e.kind=='tree')e.o.mx=f;else e.o.spr=f?gzFlipSpr(e.spr0):e.spr0;gzSet(e,p.cx,p.by,p.s)}
{const _dt=drawTree;drawTree=function(c,t){if(!t.mx)return _dt(c,t);const cx=t.x+14;c.save();c.translate(cx,0);c.scale(-1,1);c.translate(-cx,0);_dt(c,t);c.restore()}}

