const CUBIC11_B64='';
const VFONT={cubic:['俐方體 11 號','像素點陣字，跟像素畫最搭','"Cubic11"'],huninn:['jf open 粉圓','圓滾滾、可愛好讀','"Huninn"'],noto:['思源黑體','方正俐落、最清楚','"Noto Sans TC"'],sys:['系統預設','用裝置內建的字','"PingFang TC","Microsoft JhengHei"']};
const EMOJI_STACK='"Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji"';
