function fontLoadGoogle(k){if(k!='huninn'&&k!='noto')return;const id='gf_'+k;if(document.getElementById(id))return;const l=document.createElement('link');l.id=id;l.rel='stylesheet';l.href=k=='huninn'?'https://fonts.googleapis.com/css2?family=Huninn&display=swap':'https://fonts.googleapis.com/css2?family=Noto+Sans+TC:wght@400;700&display=swap';document.head.appendChild(l)}
function fontApply(k){FONT_KEY=k;try{localStorage.setItem('pxFont',k)}catch(e){}fontLoadGoogle(k);document.documentElement.style.setProperty('--gfont',fontStack());try{document.fonts&&document.fonts.load('16px '+VFONT[k][2].split(',')[0])}catch(e){}}
fontApply(FONT_KEY);
// 畫布上用「sans-serif」的文字，自動換成選好的字型
{const d=Object.getOwnPropertyDescriptor(CanvasRenderingContext2D.prototype,'font');if(d&&d.set)Object.defineProperty(CanvasRenderingContext2D.prototype,'font',{configurable:true,get(){return d.get.call(this)},set(v){d.set.call(this,typeof v=='string'&&/(^|[\s,])sans-serif\s*$/.test(v)&&!/Emoji/.test(v)?v.replace(/sans-serif\s*$/,fontStack()):v)}})}
