 howl(m,X,TG,a){const id=a[4];if(X.G.mobs.filter(o=>o.id==id).length>=6)return m.t=2;m.st='howl';m.at=.7;m.vx=0;m.ak=a},
 blink(m,X,TG,a){m.st='hide';m.at=.4;m.vx=0},
