/* v12.6 深藍海域：冠宏用 GPT 美化的怪物圖（已裁切、縮放、對齊腳底） */
const VIMG={"sea_shrimp":{"w":100,"h":82,"mode":"bottom","f":{"attack":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"],"idle":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"],"move":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"],"windup":["data:image/png;base64,","data:image/png;base64,"]}},"sea_crab":{"w":91,"h":60,"mode":"bottom","f":{"attack":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"],"guard":["data:image/png;base64,","data:image/png;base64,"],"idle":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"],"move":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"],"windup":["data:image/png;base64,","data:image/png;base64,"]}},"sea_puffer":{"w":91,"h":93,"mode":"center","f":{"attack":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"],"idle":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"],"move":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"],"windup":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"]}}};
// 圖片載入（每一格一張圖；_k＝縮放係數，因為圖是用螢幕解析度做的）
const VIMGI={};for(const k in VIMG){VIMGI[k]={};for(const a in VIMG[k].f)VIMGI[k][a]=VIMG[k].f[a].map(u=>{const im=new Image();im.src=u;im._k=.5;return im})}
// 依照怪物目前的狀態挑動畫格
function vbImg(m,id){const F=VIMGI[id];if(!F)return null;let act='idle',p=null;const st=m.st,T=m.T;
 if(st=='guard'&&F.guard)act='guard';
 else if(['wind','pounceW','shoot','puff','tongue','slam','cast','howl','hide'].includes(st)){act=F.windup?'windup':'attack';p=1-Math.max(0,m.at)/(m.ad||.5)}
 else if(st=='dash'||st=='pounce'){act='attack';p=1-Math.max(0,m.at)/(m.ad||.42)}
 else if(m.aa>0&&F.attack){act='attack';p=1-m.aa/.4}
 else if(Math.abs(m.vx)>15||(T.mv=='float'&&Math.hypot(m.vx,m.vy||0)>25))act='move';
 const L=F[act]||F.idle,i=p!=null?Math.max(0,Math.min(L.length-1,Math.floor(p*L.length))):Math.floor(m.ph*(act=='move'?9:5))%L.length,im=L[i];return im&&im.complete&&im.naturalWidth?im:null}

