addEventListener('pointerup',ev=>{const d=TL.drag;if(!d)return;TL.drag=null;ev.stopImmediatePropagation();d.l.ix=tlIx(d.l.x,d.l.y);tlRebuild();tlPush(d.before);gzRefresh()},true);
